sp_widget.client_script:
api.controller=function($rootScope, $scope,spUtil) {
	/* widget controller */
	var c = this;

	c.selectedItem = function(idx) {
		var id = c.data.notes[idx].sys_id;
		console.log('Note ID: ' + id);
		$rootScope.noteID = id;
		$rootScope.$emit('selectNote', id);
	}

	$rootScope.$on('updateNoteList',function (){
		c.server.get({
			//action:'getNotes'
		}).then(function(r){
			c.data.notes = r.data.notes
		})
	})

	c.snNoteUpdate = function(name, noteId){
		for(var i = 0; i< c.data.notes.length;i++){
				if(c.data.notes[i].sys_id == noteId){
					if(name.data.record.note){
						c.data.notes[i].note = name.data.record.note.display_value;
					}else if(name.data.record.title){
						c.data.notes[i].title = name.data.record.title.display_value;
					}
					c.server.update();
				}

		}
	}
	c.snNoteDelete = function (noteId){
		c.server.get({
			action:'deleteNote',
			noteId: noteId
		}).then(function(r){
			c.data.notes = r.data.notes
		})

	}




	spUtil.recordWatch($scope, "x_snc_createnotes_note",'', function(name) {
		if(name.data.operation == 'insert'){
			c.server.refresh();
		}
		if(name.data.operation == "update"){
			console.log(name.data);
			c.snNoteUpdate(name, name.data.sys_id);
		}
		if(name.data.operation == 'delete'){
			c.snNoteDelete(name.data.sys_id);
		}
	});

};

sp_widget.script:
(function() {

	//create an array to populate with notes
	data.notes = [];
	var noteGR = new GlideRecord('x_snc_createnotes_note');
	noteGR.addQuery('user', gs.getUser().getID());
	noteGR.orderByDesc('sys_created_on');
	noteGR.setLimit(options.maximum_records_to_display);
	noteGR.query();
	while (noteGR.next()) {
		var noteObj = {};
		//use service portal helper method to get some display values
		$sp.getRecordDisplayValues(noteObj, noteGR, 'number,title,sys_id,note');
		//get the first 20 characters of the description
		//noteObj.note = noteGR.getValue('note').slice(0,20);
		//push the populated obj into the array
		data.notes.push(noteObj);
	}

	if(input && input.action == 'deleteNote'){
		var grNote = new GlideRecord('x_snc_createnotes_note');
		if(grNote.get(input.noteId)){
			grNote.deleteRecord();
		}

	}

})();
